  rect('#162e3c', 2, -5, 5, 10); rect('#91cee0', 3, -4, 3, 7);
  rect('#ffffffcc', -2, -5, 2, 10); rect('#ffe6a5', 11, -5, 2, 3); rect('#ffe6a5', 11, 2, 2, 3);
  rect('#ff6c54', -13, -5, 1, 3); rect('#ff6c54', -13, 2, 1, 3);
