  c.fillStyle = theme.fleck; c.fillRect(6, 8, 19, 2); c.fillRect(65, 47, 23, 2);
  c.fillStyle = theme.shoulder; c.fillRect(0, 28, canvas.width, 21);
  c.fillStyle = theme.road; c.fillRect(0, 31, canvas.width, 15);
