const mix = (a, b, t) => a + (b - a) * t;
const NEON = {
  green: { rgb: [.4, 1, .38], hex: '#66ff61' },
  purple: { rgb: [.8, .4, 1], hex: '#cc66ff' },
  yellow: { rgb: [1, .92, .3], hex: '#ffeb4d' }
